type Props = ComponentProps<typeof PromoMainBlockDesktop>;
// raw Background не соответствует матрице контракта; значение не исправлено автоматически
function Example({ imageProps, backgroundColor, onPrimaryAction }: { imageProps: NonNullable<Props['imageProps']> & { src: string; alt: string }; backgroundColor?: Props['backgroundColor']; onPrimaryAction: NonNullable<Props['primaryButtonProps']>['onClick'] }) {
    return <PromoMainBlockDesktop
        title={"Title"}
        subtitle={"Subtitle"}
        appearance="light"
        withBackground={true}
        imageProps={imageProps}
        backgroundColor={backgroundColor}
        view="page" compact={false} blurEffect={true}
        primaryButtonProps={{ label: "Label", onClick: onPrimaryAction }}

        buttonsGroupLayout="horizontal"



    />;
}

